WITH returns_by_gender AS (SELECT cr.cr_returned_date_sk AS return_date_sk, cd.cd_gender AS gender, cr.cr_net_loss AS net_loss FROM catalog_returns cr JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk UNION ALL SELECT sr.sr_returned_date_sk AS return_date_sk, cd.cd_gender AS gender, sr.sr_net_loss AS net_loss FROM store_returns sr JOIN customer_demographics cd ON sr.sr_cdemo_sk = cd.cd_demo_sk), daily AS (SELECT return_date_sk, gender, SUM(net_loss) AS daily_net_loss FROM returns_by_gender GROUP BY return_date_sk, gender) SELECT return_date_sk, gender, daily_net_loss, SUM(daily_net_loss) OVER (PARTITION BY gender ORDER BY return_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss, DENSE_RANK() OVER (PARTITION BY gender ORDER BY daily_net_loss DESC) AS daily_loss_rank FROM daily ORDER BY gender, return_date_sk
